59	func Scan(opts Options) ([]Finding, error) {
60		root := opts.Root
61		if root == "" {
62			root = "."
63		}
64	
65		var findings []Finding
66		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
67			if err != nil {
68				return err
69			}
70			rel, err := filepath.Rel(root, path)
71			if err != nil {
72				return err
73			}
74			rel = filepath.ToSlash(rel)
75			if rel == "." {
76				return nil
77			}
78			if d.IsDir() {
79				if shouldSkipDir(rel) {
80					return filepath.SkipDir
81				}
82				return nil
83			}
84			if skippedFiles[rel] {
85				return nil
86			}
87			if !isTextCandidate(rel) {
88				return nil
89			}
90			fileFindings, err := scanFile(root, rel)
91			if err != nil {
92				return err
93			}
94			findings = append(findings, fileFindings...)
95			return nil
96		})
97		if err != nil {
98			return nil, err
99		}
100		sort.Slice(findings, func(i, j int) bool {
101			if findings[i].Path != findings[j].Path {
102				return findings[i].Path < findings[j].Path
103			}
104			if findings[i].Line != findings[j].Line {
105				return findings[i].Line < findings[j].Line
106			}
107			return findings[i].Column < findings[j].Column
108		})
109		return findings, nil
110	}
