112	func Report(w io.Writer, findings []Finding) error {
113		if w == nil {
114			return nil
115		}
116		if len(findings) == 0 {
117			_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
118			return err
119		}
120		if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
121			return err
122		}
123		for _, f := range findings {
124			if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %q\n", f.Path, f.Line, f.Column, f.Surface, f.Match); err != nil {
125				return err
126			}
127		}
128		return nil
129	}
