15	// ClaudeQuotaSnapshot captures Claude's current-quota headroom as absolute
16	// token/message counts. It is written to a durable per-user cache by an
17	// asynchronous capture path and read by foreground routing consumers.
18	//
19	// The snapshot is intentionally distinct from the percentage-based
20	// QuotaSignal: foreground routing needs concrete numbers to reason about
21	// 5-hour / weekly headroom without invoking PTY capture inline.
22	type ClaudeQuotaSnapshot struct {
23		CapturedAt        time.Time              `json:"captured_at"`
24		FiveHourRemaining int                    `json:"five_hour_remaining"`
25		FiveHourLimit     int                    `json:"five_hour_limit"`
26		WeeklyRemaining   int                    `json:"weekly_remaining"`
27		WeeklyLimit       int                    `json:"weekly_limit"`
28		Source            string                 `json:"source"` // e.g. "pty", "heuristic"
29		Account           *harnesses.AccountInfo `json:"account,omitempty"`
30	}
31	
32	// DefaultClaudeQuotaStaleAfter is the default maximum age before a cached
33	// snapshot is considered stale and foreground routing should fall back to
34	// the safe default.
35	const DefaultClaudeQuotaStaleAfter = 15 * time.Minute
36	
37	// claudeQuotaCacheEnv lets tests override the cache file path.
38	const claudeQuotaCacheEnv = "DDX_AGENT_CLAUDE_QUOTA_CACHE"
39	
40	// claudeQuotaCacheEnvLegacy is the old DDx env var, read during the
41	// one-minor-version back-compat window. Removed at v0.5.0.
42	const claudeQuotaCacheEnvLegacy = "DDX_CLAUDE_QUOTA_CACHE"
43	
44	// ClaudeQuotaCachePath returns the durable location for the Claude quota
45	// cache. It resolves to $XDG_STATE_HOME/<config-dir>/claude-quota.json, or
46	// ~/.local/state/<config-dir>/claude-quota.json when XDG_STATE_HOME is unset.
47	// The DDX_AGENT_CLAUDE_QUOTA_CACHE env var takes precedence (primarily for
48	// tests).
49	func ClaudeQuotaCachePath() (string, error) {
50		if path := os.Getenv(claudeQuotaCacheEnv); path != "" {
51			return path, nil
52		}
53		if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
54			return filepath.Join(xdg, productinfo.ConfigDir, "claude-quota.json"), nil
55		}
56		home, err := os.UserHomeDir()
57		if err != nil {
58			return "", err
59		}
60		return filepath.Join(home, ".local", "state", productinfo.ConfigDir, "claude-quota.json"), nil
61	}
62	
63	// claudeQuotaCachePathLegacy returns the OLD DDx cache path used before the
64	// path-namespace rebase. It is consulted during the back-compat read window
65	// when the new path yields no snapshot. Removed at v0.5.0.
66	func claudeQuotaCachePathLegacy() (string, error) {
67		if path := os.Getenv(claudeQuotaCacheEnvLegacy); path != "" {
68			return path, nil
69		}
70		if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
71			return filepath.Join(xdg, "ddx", "claude-quota.json"), nil
72		}
73		home, err := os.UserHomeDir()
74		if err != nil {
75			return "", err
76		}
77		return filepath.Join(home, ".local", "state", "ddx", "claude-quota.json"), nil
78	}
79	
80	// WriteClaudeQuota atomically persists a ClaudeQuotaSnapshot to the given
81	// path. The parent directory is created if necessary. The file is written
82	// to a sibling .tmp file and renamed into place so readers never observe a
83	// partially-written snapshot. The final file mode is 0600.
84	func WriteClaudeQuota(path string, snapshot ClaudeQuotaSnapshot) error {
85		if path == "" {
86			return fmt.Errorf("claude quota cache path is empty")
87		}
88		if snapshot.CapturedAt.IsZero() {
89			snapshot.CapturedAt = time.Now().UTC()
90		} else {
91			snapshot.CapturedAt = snapshot.CapturedAt.UTC()
92		}
93	
94		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
95			return fmt.Errorf("create claude quota cache dir: %w", err)
96		}
97	
98		data, err := json.MarshalIndent(snapshot, "", "  ")
99		if err != nil {
100			return fmt.Errorf("marshal claude quota snapshot: %w", err)
101		}
102		data = append(data, '\n')
103	
104		tmpPath := path + ".tmp"
105		if err := os.WriteFile(tmpPath, data, 0o600); err != nil {
106			return fmt.Errorf("write claude quota cache tmp: %w", err)
107		}
108		if err := os.Rename(tmpPath, path); err != nil {
109			_ = os.Remove(tmpPath)
110			return fmt.Errorf("rename claude quota cache: %w", err)
111		}
112		// Ensure final mode is 0600 in case an older file had a different mode.
113		if err := os.Chmod(path, 0o600); err != nil {
114			return fmt.Errorf("chmod claude quota cache: %w", err)
115		}
116		return nil
117	}
118	
119	// ReadClaudeQuotaFrom reads the snapshot at the given path. Returns
120	// (nil, false) if the file does not exist or cannot be decoded. Non-
121	// existence is NOT an error: foreground callers are expected to fall back
122	// to a safe default when no snapshot is present.
123	func ReadClaudeQuotaFrom(path string) (*ClaudeQuotaSnapshot, bool) {
124		data, err := os.ReadFile(path)
125		if err != nil {
126			return nil, false
127		}
128		var snap ClaudeQuotaSnapshot
129		if err := json.Unmarshal(data, &snap); err != nil {
130			return nil, false
131		}
132		return &snap, true
133	}
134	
135	// ReadClaudeQuota tries the new path first, then falls back to the old
136	// path for one minor-version transition window. After v0.5.0, the back-compat
137	// fallback is removed.
138	//
139	// The second return value is false if no snapshot is present or cannot be
140	// decoded in either location.
141	//
142	// Callers SHOULD check snapshot age via ClaudeQuotaSnapshotAge (or
143	// IsClaudeQuotaFresh) before trusting the values; this function does not
144	// itself enforce a TTL so that callers can report stale snapshots in
145	// diagnostic surfaces like `ddx agent doctor --routing`.
146	func ReadClaudeQuota() (*ClaudeQuotaSnapshot, bool) {
147		path, err := ClaudeQuotaCachePath()
148		if err != nil {
149			return nil, false
150		}
151		if snap, ok := ReadClaudeQuotaFrom(path); ok {
152			return snap, true
153		}
154	
155		// Back-compat fallback: read from the old DDx path during the
156		// one-minor-version transition window. Removed at v0.5.0.
157		legacyPath, err := claudeQuotaCachePathLegacy()
158		if err != nil {
159			return nil, false
160		}
161		return ReadClaudeQuotaFrom(legacyPath)
162	}
163	
164	// ClaudeQuotaSnapshotAge reports the age of a snapshot relative to now.
165	// A zero or future CapturedAt yields a zero age.
166	func ClaudeQuotaSnapshotAge(snapshot *ClaudeQuotaSnapshot, now time.Time) time.Duration {
167		if snapshot == nil || snapshot.CapturedAt.IsZero() {
168			return 0
169		}
170		age := now.UTC().Sub(snapshot.CapturedAt.UTC())
171		if age < 0 {
172			return 0
173		}
174		return age
175	}
176	
177	// IsClaudeQuotaFresh reports whether a snapshot exists and is newer than
178	// staleAfter relative to now. A nil snapshot is never fresh. A zero
179	// staleAfter falls back to DefaultClaudeQuotaStaleAfter.
180	func IsClaudeQuotaFresh(snapshot *ClaudeQuotaSnapshot, now time.Time, staleAfter time.Duration) bool {
181		if snapshot == nil || snapshot.CapturedAt.IsZero() {
182			return false
183		}
184		if staleAfter <= 0 {
185			staleAfter = DefaultClaudeQuotaStaleAfter
186		}
187		return ClaudeQuotaSnapshotAge(snapshot, now) <= staleAfter
188	}
189	
190	// ClaudeQuotaRoutingDecision summarises what foreground routing should do
191	// given the current cached snapshot.
192	type ClaudeQuotaRoutingDecision struct {
193		// PreferClaude is true when a fresh snapshot shows headroom in both the
194		// 5-hour and weekly windows. When false, routing should prefer a
195		// non-claude fallback harness.
196		PreferClaude bool
197		// SnapshotPresent is true when a snapshot was found in the cache (even
198		// if stale).
199		SnapshotPresent bool
200		// Fresh is true when the snapshot is present and newer than staleAfter.
201		Fresh bool
202		// Age is the age of the snapshot relative to now (zero when absent).
203		Age time.Duration
204		// Snapshot is the cached snapshot when present.
205		Snapshot *ClaudeQuotaSnapshot
206		// Reason describes why the decision was made (diagnostic surface).
207		Reason string
208	}
209	
210	// DecideClaudeQuotaRouting turns a cached snapshot into a routing decision
211	// for foreground callers. When the snapshot is missing or stale, the safe
212	// default is NOT to prefer claude (assume limited).
213	//
214	// A snapshot counts as "limited" when either window reports zero or
215	// negative remaining headroom.
216	func DecideClaudeQuotaRouting(snapshot *ClaudeQuotaSnapshot, now time.Time, staleAfter time.Duration) ClaudeQuotaRoutingDecision {
217		decision := ClaudeQuotaRoutingDecision{
218			Snapshot: snapshot,
219		}
220		if snapshot == nil {
221			decision.Reason = "no cached snapshot; assume limited"
222			return decision
223		}
224		decision.SnapshotPresent = true
225		decision.Age = ClaudeQuotaSnapshotAge(snapshot, now)
226		if !IsClaudeQuotaFresh(snapshot, now, staleAfter) {
227			decision.Reason = "cached snapshot is stale; assume limited"
228			return decision
229		}
230		if err := validateClaudeQuotaSnapshotForRouting(snapshot); err != nil {
231			decision.Reason = "cached snapshot is incomplete: " + err.Error() + "; assume limited"
232			return decision
233		}
234		decision.Fresh = true
235		if snapshot.FiveHourRemaining <= 0 || snapshot.WeeklyRemaining <= 0 {
236			decision.Reason = "fresh snapshot reports exhausted window; assume limited"
237			return decision
238		}
239		decision.PreferClaude = true
240		decision.Reason = "fresh snapshot has headroom"
241		return decision
242	}
243	
244	func validateClaudeQuotaSnapshotForRouting(snapshot *ClaudeQuotaSnapshot) error {
245		if snapshot == nil {
246			return fmt.Errorf("missing snapshot")
247		}
248		if strings.TrimSpace(snapshot.Source) == "" {
249			return fmt.Errorf("missing source")
250		}
251		if snapshot.Account == nil || strings.TrimSpace(snapshot.Account.PlanType) == "" {
252			return fmt.Errorf("missing account plan")
253		}
254		if snapshot.FiveHourLimit <= 0 {
255			return fmt.Errorf("invalid 5h limit")
256		}
257		if snapshot.WeeklyLimit <= 0 {
258			return fmt.Errorf("invalid weekly limit")
259		}
260		if snapshot.FiveHourRemaining < 0 || snapshot.FiveHourRemaining > snapshot.FiveHourLimit {
261			return fmt.Errorf("invalid 5h remaining")
262		}
263		if snapshot.WeeklyRemaining < 0 || snapshot.WeeklyRemaining > snapshot.WeeklyLimit {
264			return fmt.Errorf("invalid weekly remaining")
265		}
266		return nil
267	}
268	
269	// ReadClaudeQuotaRoutingDecision is a convenience wrapper that reads the
270	// default cache and produces a routing decision in one call. It is the
271	// entry point foreground routing should use instead of any inline PTY
272	// capture.
273	func ReadClaudeQuotaRoutingDecision(now time.Time, staleAfter time.Duration) ClaudeQuotaRoutingDecision {
274		snap, _ := ReadClaudeQuota()
275		return DecideClaudeQuotaRouting(snap, now, staleAfter)
276	}
277	
278	// RefreshClaudeQuotaAsync launches a background goroutine that invokes
279	// capture and writes the result to the default cache path. It returns
280	// immediately; callers never block on capture.
281	//
282	// The capture function is injected so that the durable cache layer does
283	// not depend on any specific PTY implementation. A future `ddx claude
284	// refresh-quota` subcommand can pass a real PTY-backed capture; tests can
285	// pass deterministic fakes.
286	//
287	// If capture returns an error, the cache is not touched.
288	func RefreshClaudeQuotaAsync(capture func() (ClaudeQuotaSnapshot, error)) {
289		if capture == nil {
290			return
291		}
292		go func() {
293			snap, err := capture()
294			if err != nil {
295				return
296			}
297			path, pathErr := ClaudeQuotaCachePath()
298			if pathErr != nil {
299				return
300			}
301			_ = WriteClaudeQuota(path, snap)
302		}()
303	}
